// CONFIGURACIÓN. Es lo único que se edita en este flujo; sirve a uno o a varios clientes de Reymen.
// - verifyToken: palabra que tú inventas y pones igual en Meta (App → Webhooks → «Verify token»).
// - appSecret: App → Configuración → Básica → «Clave secreta de la app». Sirve para comprobar que los avisos son de Meta.
// - clientes: un renglón por negocio, con su Página de Facebook y (si tiene) su cuenta de Instagram conectada a esa página.
//   pageToken = token de acceso de la PÁGINA (permisos pages_messaging, instagram_manage_messages, leads_retrieval,
//   pages_manage_metadata). orgId y llave en Reymen: Admin → Clientes → (cliente) → botón de webhook.
//   Tokens y llave son secretos: no exportes ni compartas este flujo con ellos puestos.
const cfg = {
  reymenUrl: 'https://app.reymen.mx',
  graph: 'https://graph.facebook.com/v21.0',
  verifyToken: 'INVENTA_UNA_PALABRA_SECRETA',
  appSecret: '',
  clientes: [
    { nombre: 'Mi negocio', pageId: '000000000000000', instagramId: '', pageToken: 'PEGA_AQUI_EL_TOKEN_DE_LA_PAGINA', orgId: 'PEGA_AQUI_EL_ID_DE_LA_ORGANIZACION', llave: 'PEGA_AQUI_LA_LLAVE_DE_CONEXION', fuenteLeads: 'Meta Lead Ads' },
  ],
};
const ruta = $('Meta: verificación').isExecuted ? 'verificar' : $('Meta: avisos').isExecuted ? 'avisos' : 'saliente';
const item = $input.first();
return [{ json: { ruta, cfg, req: item.json }, binary: item.binary }];

// Meta comprueba el webhook una vez: si el token coincide, se le regresa el «challenge».
const { cfg, req } = $input.first().json;
const q = req.query || {};
if (q['hub.mode'] !== 'subscribe' || q['hub.verify_token'] !== cfg.verifyToken) throw new Error('Token de verificación incorrecto');
return [{ json: { challenge: String(q['hub.challenge'] || '') } }];

const crypto = require('crypto');
// Firma de Reymen (entrada /api/webhooks/n8n/*): sha256= + HMAC-SHA256 hex de "<timestamp>.<cuerpo>" con la llave del cliente.
function firmar(llave, body) {
  const ts = String(Date.now());
  return { ts, sig: 'sha256=' + crypto.createHmac('sha256', llave).update(ts + '.' + body).digest('hex') };
}
// Cuerpo crudo que llegó al webhook (opción "Raw Body"), para verificar firmas byte por byte.
function crudo(item) {
  return item.binary && item.binary.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(item.json.body || {});
}
// Verifica que el aviso venga de Reymen (firma de plataforma con N8N_WEBHOOK_SECRET y hora dentro de ±5 min).
function verificarReymen(item) {
  const secret = $env.N8N_WEBHOOK_SECRET;
  const h = item.json.headers || {};
  const raw = crudo(item);
  const ts = String(h['x-reymen-timestamp'] || '');
  const sig = String(h['x-reymen-signature'] || '');
  const esperado = 'sha256=' + crypto.createHmac('sha256', secret || '').update(ts + '.' + raw).digest('hex');
  if (!secret || !ts || Math.abs(Date.now() - Number(ts)) > 5 * 60 * 1000 || sig.length !== esperado.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(esperado))) {
    throw new Error('Firma de Reymen inválida');
  }
  return JSON.parse(raw);
}

// Avisos de Meta: mensajes de Messenger e Instagram → bandeja de Reymen; Lead Ads → contacto nuevo en Reymen.
// Se responde a Meta al instante (el webhook está en «Immediately»); aquí se procesa con calma.
const { cfg, req } = $input.first().json;
const raw = crudo({ json: req, binary: $input.first().binary });
if (cfg.appSecret) {
  const firma = String((req.headers || {})['x-hub-signature-256'] || '');
  const esperado = 'sha256=' + crypto.createHmac('sha256', cfg.appSecret).update(raw).digest('hex');
  if (firma.length !== esperado.length || !crypto.timingSafeEqual(Buffer.from(firma), Buffer.from(esperado))) throw new Error('Firma de Meta inválida');
}
const aviso = JSON.parse(raw);
const http = (opts) => this.helpers.httpRequest(opts);
const enviar = async (c, ruta, payload, eventId) => {
  const body = JSON.stringify(payload);
  const f = firmar(c.llave, body);
  await http({ method: 'POST', url: cfg.reymenUrl + ruta, body, json: false, headers: { 'content-type': 'application/json', 'x-reymen-orgid': c.orgId, 'x-reymen-timestamp': f.ts, 'x-reymen-signature': f.sig, 'x-reymen-event-id': eventId } });
};
const resultado = [];
for (const entry of aviso.entry || []) {
  const esInstagram = aviso.object === 'instagram';
  const c = cfg.clientes.find((x) => (esInstagram ? x.instagramId : x.pageId) === String(entry.id));
  if (!c) { resultado.push({ omitido: 'cuenta ' + entry.id + ' no está en Configuración' }); continue; }

  // Mensajes (Messenger o Instagram Direct)
  for (const ev of entry.messaging || []) {
    const m = ev.message;
    if (!m || m.is_echo || !ev.sender || !m.mid) continue; // lo que escribe la propia página no se reingresa
    const adjunto = (m.attachments || [])[0];
    const contenido = String(m.text || '').trim() || (adjunto ? '📎 Envió un archivo (' + (adjunto.type || 'adjunto') + '). Ábrelo en ' + (esInstagram ? 'Instagram' : 'Messenger') + '.' : '');
    if (!contenido) continue;
    let nombre;
    try {
      const perfil = await http({ method: 'GET', url: cfg.graph + '/' + ev.sender.id, qs: { fields: esInstagram ? 'name,username' : 'name', access_token: c.pageToken }, json: true });
      nombre = perfil.name || (perfil.username ? '@' + perfil.username : undefined);
    } catch (e) { /* sin nombre: la bandeja muestra el usuario */ }
    await enviar(c, '/api/webhooks/n8n/conversations', {
      channel: esInstagram ? 'instagram' : 'messenger',
      contactHandle: String(ev.sender.id),
      contactName: nombre,
      message: { role: 'USER', content: contenido, externalId: m.mid },
    }, 'meta:' + m.mid);
    resultado.push({ mensaje: m.mid, canal: esInstagram ? 'instagram' : 'messenger' });
  }

  // Lead Ads: Meta solo manda el id; los datos del formulario se piden a la Graph API.
  for (const ch of entry.changes || []) {
    if (ch.field !== 'leadgen' || !ch.value || !ch.value.leadgen_id) continue;
    const lead = await http({ method: 'GET', url: cfg.graph + '/' + ch.value.leadgen_id, qs: { fields: 'created_time,field_data,ad_name,campaign_name,form_id,ad_id', access_token: c.pageToken }, json: true });
    const campos = {};
    for (const f of lead.field_data || []) campos[f.name] = (f.values || []).join(', ');
    const nombre = campos.full_name || [campos.first_name, campos.last_name].filter(Boolean).join(' ') || campos.email || campos.phone_number || 'Lead de Meta';
    const conocidos = ['full_name', 'first_name', 'last_name', 'email', 'phone_number'];
    const respuestas = Object.fromEntries(Object.entries(campos).filter(([k]) => !conocidos.includes(k)));
    await enviar(c, '/api/webhooks/n8n/leads', {
      name: nombre,
      email: campos.email || undefined,
      phone: campos.phone_number || undefined,
      source: c.fuenteLeads || 'Meta Lead Ads',
      externalId: 'meta-lead:' + ch.value.leadgen_id,
      metadata: { formId: ch.value.form_id || lead.form_id, adId: ch.value.ad_id || lead.ad_id, adName: lead.ad_name, campaign: lead.campaign_name, createdTime: lead.created_time, respuestas },
    }, 'meta-lead:' + ch.value.leadgen_id);
    resultado.push({ lead: ch.value.leadgen_id });
  }
}
return [{ json: { procesados: resultado } }];

const crypto = require('crypto');
// Firma de Reymen (entrada /api/webhooks/n8n/*): sha256= + HMAC-SHA256 hex de "<timestamp>.<cuerpo>" con la llave del cliente.
function firmar(llave, body) {
  const ts = String(Date.now());
  return { ts, sig: 'sha256=' + crypto.createHmac('sha256', llave).update(ts + '.' + body).digest('hex') };
}
// Cuerpo crudo que llegó al webhook (opción "Raw Body"), para verificar firmas byte por byte.
function crudo(item) {
  return item.binary && item.binary.data ? Buffer.from(item.binary.data.data, 'base64').toString('utf8') : JSON.stringify(item.json.body || {});
}
// Verifica que el aviso venga de Reymen (firma de plataforma con N8N_WEBHOOK_SECRET y hora dentro de ±5 min).
function verificarReymen(item) {
  const secret = $env.N8N_WEBHOOK_SECRET;
  const h = item.json.headers || {};
  const raw = crudo(item);
  const ts = String(h['x-reymen-timestamp'] || '');
  const sig = String(h['x-reymen-signature'] || '');
  const esperado = 'sha256=' + crypto.createHmac('sha256', secret || '').update(ts + '.' + raw).digest('hex');
  if (!secret || !ts || Math.abs(Date.now() - Number(ts)) > 5 * 60 * 1000 || sig.length !== esperado.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(esperado))) {
    throw new Error('Firma de Reymen inválida');
  }
  return JSON.parse(raw);
}

// Respuesta escrita en la bandeja de Reymen (o por el Agente IA) → Instagram o Messenger del cliente final.
// Si algo falla, el flujo responde error y Reymen marca el mensaje como «no enviado».
// Meta solo deja contestar dentro de las 24 h desde el último mensaje del cliente (política de mensajería estándar).
const { cfg } = $input.first().json;
const reymen = verificarReymen({ json: $input.first().json.req, binary: $input.first().binary });
const d = reymen.data || {};
const c = cfg.clientes.find((x) => x.orgId === reymen.organizationId);
if (!c) throw new Error('La organización ' + reymen.organizationId + ' no está en Configuración → clientes');
if (!d.contactHandle) throw new Error('La conversación no tiene el usuario de Meta del contacto');
const message = d.attachmentUrl
  ? { attachment: { type: d.attachmentType === 'image' ? 'image' : 'file', payload: { url: d.attachmentUrl, is_reusable: false } } }
  : { text: String(d.content || '') };
const res = await this.helpers.httpRequest({
  method: 'POST', url: cfg.graph + '/me/messages', qs: { access_token: c.pageToken }, json: true,
  body: { recipient: { id: d.contactHandle }, messaging_type: 'RESPONSE', message },
});
if (d.attachmentUrl && d.content) {
  await this.helpers.httpRequest({ method: 'POST', url: cfg.graph + '/me/messages', qs: { access_token: c.pageToken }, json: true, body: { recipient: { id: d.contactHandle }, messaging_type: 'RESPONSE', message: { text: String(d.content) } } });
}
return [{ json: { enviado: true, metaMessageId: res.message_id || null } }];
